func:
if (flow.get('tempThreshold') === undefined) {
    flow.set('tempThreshold', 30.0);
}
msg.topic = "CREATE TABLE IF NOT EXISTS sensor_history (id INTEGER PRIMARY KEY AUTOINCREMENT, suhu REAL, kelembaban REAL, timestamp TEXT, received TEXT);";
return msg;

var data = msg.payload;
data.received = new Date().toISOString();
flow.set('lastSensor', data);

var threshold = flow.get('tempThreshold') || 30.0;
var isAlert = data.suhu > threshold;

var sqlMsg = {
    topic: `INSERT INTO sensor_history (suhu, kelembaban, timestamp, received) VALUES (${data.suhu}, ${data.kelembaban}, '${data.timestamp}', '${data.received}');`
};

var wsMsg = {
    payload: JSON.stringify({
        type: 'sensor_update',
        data: data,
        threshold: threshold,
        alert: isAlert,
        alert_message: isAlert ? `PERINGATAN! Suhu (${data.suhu}°C) melebihi batas (${threshold}°C)!` : null
    })
};

var alertMqttMsg = null;
if (isAlert) {
    alertMqttMsg = {
        topic: 'iot/alert',
        payload: JSON.stringify({
            status: 'WARNING',
            message: `Suhu tinggi terdeteksi: ${data.suhu}°C (Batas: ${threshold}°C)`,
            timestamp: data.received
        })
    };
}

return [sqlMsg, wsMsg, alertMqttMsg];

const VALID_KEY = 'RAHASIABANGAT123';
const apiKey = msg.req.headers['x-api-key'];
msg.headers = {'Access-Control-Allow-Origin': '*'};

if (apiKey !== VALID_KEY) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    return msg;
}

var data = flow.get('lastSensor') || { suhu: null, kelembaban: null, timestamp: null };
var threshold = flow.get('tempThreshold') || 30.0;
msg.statusCode = 200;
msg.payload = {
    status: 'success',
    data: data,
    threshold: threshold,
    server_time: new Date().toISOString()
};
return msg;

const VALID_KEY = 'RAHASIABANGAT123';
const apiKey = msg.req.headers['x-api-key'];
msg.headers = {'Access-Control-Allow-Origin': '*'};

if (apiKey !== VALID_KEY) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    return [null, msg];
}

msg.topic = "SELECT suhu, kelembaban, timestamp, received FROM sensor_history ORDER BY id DESC LIMIT 50;";
return [msg, null];

var rows = (msg.payload || []).reverse();
msg.statusCode = 200;
msg.headers = {'Access-Control-Allow-Origin': '*'};
msg.payload = {
    status: 'success',
    count: rows.length,
    data: rows
};
return msg;

const VALID_KEY = 'RAHASIABANGAT123';
const apiKey = msg.req.headers['x-api-key'];
msg.headers = {'Access-Control-Allow-Origin': '*'};

if (apiKey !== VALID_KEY) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    return [msg, null];
}

var body = msg.payload;
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'device dan action wajib diisi' };
    return [msg, null];
}

var mqttMsg = { payload: JSON.stringify(body), topic: 'iot/kontrol' };
msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Perintah terkirim',
    sent: body
};
return [msg, mqttMsg];

const VALID_KEY = 'RAHASIABANGAT123';
const apiKey = msg.req.headers['x-api-key'];
msg.headers = {'Access-Control-Allow-Origin': '*'};

if (apiKey !== VALID_KEY) {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    return msg;
}

var nilai = parseFloat(msg.payload.threshold);
if (isNaN(nilai)) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Field threshold harus berupa angka' };
    return msg;
}

flow.set('tempThreshold', nilai);
msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Batas suhu berhasil diperbarui',
    threshold: nilai
};
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
